mapper.select:
select r.* , case when r.CHECKRESTATUS= '01' then '有偏差' else '无偏差' end CHECKRES/*检查结果*/ from ( select DATE_FORMAT(todayData.HOLD_DATE,'%Y%m%d') holdDate, /*查询日期*/ case when todayData.QTY <> (ifnull(todayDataDetail.shares,0) + ifnull(lastDayData.QTY, 0)) then '01' else '02' end CHECKRESTATUS,/*检查结果*/ todayData.PRODID prodId, /*产品代码*/ P.PRODNAME prodName, /*产品名称*/ P.REG_CODE prdRegistCode, /*产品登记编码*/ todayData.INDENTIFY_MARK indentifyMark, /*识别标识*/ todayData.CCY ccy, /*币种*/ todayData.QTY qty, /*当日持有份额*/ ifnull(lastDayData.QTY, 0) lastQty, /*前一日持有份额*/ todayDataDetail.shares changeQty/*当日明细变动份额*/ from (SELECT A.REGIST_BANK_CODE, A.PRODID, A.HOLD_DATE, A.CCY, SUM(A.QTY) QTY, A.INDENTIFY_MARK FROM CHB_INVESTHOLD_INFO A where A.STATUS != 'D'
AND DATE_FORMAT(A.HOLD_DATE,'%Y-%m-%d') = #{date,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
AND A.INDENTIFY_MARK LIKE concat_ws('','%',#{indentifyMark},'%')
#{item,jdbcType=VARCHAR}
GROUP BY A.REGIST_BANK_CODE, A.PRODID, A.HOLD_DATE, A.CCY, a.indentify_mark) todayData left join (SELECT A.REGIST_BANK_CODE, A.PRODID, A.HOLD_DATE, A.CCY, A.INDENTIFY_MARK, SUM(A.QTY) QTY FROM CHB_INVESTHOLD_INFO A where A.STATUS != 'D' GROUP BY A.REGIST_BANK_CODE, A.PRODID, A.HOLD_DATE, A.CCY, a.indentify_mark) lastDayData on todayData.REGIST_BANK_CODE = lastDayData.REGIST_BANK_CODE and todayData.PRODID = lastDayData.PRODID AND date_add(todayData.HOLD_DATE, interval -1 day) = lastDayData.HOLD_DATE AND todayData.CCY = lastDayData.CCY and todayData.indentify_mark = lastDayData.indentify_mark left join (select t.reg_code, t.account, t.REGIST_BANK_CODE, t.indentify_mark, t.ccy, t.equity_conf_date, sum(( case when t.busi_type in('03','11','13','15','16') then -1 * t.shares when t.busi_type in('06','07','08','09') then null else t.shares end )) shares /*当日变动份额*/ from chb_equdet t where t.STATUS != 'D' and t.busi_type not in ('06','07','08','09') /*徽商个性化,冻结，不影响份额。不纳入计算*/ group by t.REGIST_BANK_CODE, t.account, t.ccy, t.indentify_mark, reg_code, equity_conf_date) todayDataDetail on todayData.REGIST_BANK_CODE = todayDataDetail.REGIST_BANK_CODE and todayData.PRODID = todayDataDetail.account
AND date_add(todayData.HOLD_DATE, interval -1 day) = todayDataDetail.equity_conf_date
AND todayData.CCY = todayDataDetail.CCY and todayData.indentify_mark = todayDataDetail.indentify_mark LEFT JOIN CHB_PRDRESIST_CODE P ON todayData.PRODID = P.PRODID order by todayData.PRODID, todayData.HOLD_DATE, todayData.CCY )r
r.CHECKRESTATUS=#{checkResult,jdbcType=VARCHAR}
